void main() {
  test('the Dart networks give the same numbers as the notebook', () {
    expect(VitalsModel.trained, isTrue);
    for (var i = 0; i < _hr.length; i++) {
      expect(VitalsModel.forecast(VitalSignal.heartRate, _hr[i])!, closeTo(_hrExpected[i], 1e-6), reason: 'hr $i');
    }
    for (var i = 0; i < _tp.length; i++) {
      expect(VitalsModel.forecast(VitalSignal.temperature, _tp[i])!, closeTo(_tpExpected[i], 1e-6), reason: 'temp $i');
    }
  });

  test('a steady heart rate raises no alert, an erratic one does', () {
    // the network learns a new level within a minute or two, so only fast, large or erratic changes
    // stay surprising for three minutes: that is what raises the alert
    final m = VitalsMonitor(VitalSignal.heartRate);
    for (var i = 0; i < 60; i++) {
      expect(m.addMinute(70.0 + (i % 3))?.alert ?? false, isFalse);
    }
    var alerted = false;
    for (final v in <double>[135, 70, 135, 70, 135, 70, 135]) {
      alerted = (m.addMinute(v)?.alert ?? false) || alerted;
    }
    expect(alerted, isTrue);
  });
}
